\r\n            <div class=\"skill-name\">{{ skill.name }}</div>\r\n            <div class=\"skill-bar\">\r\n              <div class=\"skill-level\" :style=\"{ width: skill.percentage , background: personalInfo.theme.barColor }\"></div>\r\n            </div>\r\n          </div>\r\n        </section>\r\n\r\n\r\n\r\n        <div class=\"profile\" v-if=\"section.key === \'personalInfo\'\">\r\n          <div class=\"profile-image\">\r\n            <img :src=\"personalInfo.logo\" alt=\"Profile photo\" />\r\n          </div>\r\n          <h1>{{ personalInfo.first_name }} {{ personalInfo.last_name }}</h1>\r\n          <p class=\"title\">{{ personalInfo.job_title }}</p>\r\n        </div>\r\n\r\n        <div class=\"contact-info\" v-if=\"section.key === \'personalInfo\'\">\r\n          <div class=\"info-item\" v-if=\"personalInfo.place_of_birth\">\r\n            <span class=\"label\" data-key=\"place_of_birth\"></span>\r\n            <span>{{ personalInfo.place_of_birth }}</span>\r\n          </div>\r\n          <div class=\"info-item\" v-if=\"personalInfo.date_of_birth\">\r\n            <span class=\"label\" data-key=\"date_of_birth\"></span>\r\n            <span>{{ personalInfo.date_of_birth }}</span>\r\n          </div>\r\n          <div class=\"info-item\" v-if=\"personalInfo.email\">\r\n            <span class=\"label\" data-key=\"email2\"></span>\r\n            <span>{{ personalInfo.email }}</span>\r\n          </div>\r\n          <div class=\"info-item\" v-if=\"personalInfo.mobile\">\r\n            <span class=\"label\" data-key=\"mobile\"></span>\r\n            <span>{{ personalInfo.mobile }}</span>\r\n          </div>\r\n          <div class=\"info-item\" v-if=\"personalInfo.address\">\r\n            <span class=\"label\" data-key=\"address\"></span>\r\n            <span>{{ personalInfo.address }} - {{ personalInfo.city }} - {{ personalInfo.country }}</span>\r\n          </div>\r\n          <div class=\"info-item\" v-if=\"personalInfo.nationality\">\r\n            <span class=\"label\" data-key=\"nationality\"></span>\r\n            <span>{{ personalInfo.nationality }}</span>\r\n          </div>\r\n          <div class=\"info-item\" v-if=\"personalInfo.postal_code\">\r\n            <span class=\"label\" data-key=\"postal_code\"></span>\r\n            <span>{{ personalInfo.postal_code }}</span>\r\n          </div>\r\n          <div class=\"info-item\" v-if=\"personalInfo.driving_license\">\r\n            <span class=\"label\" data-key=\"driving_license\"></span>\r\n            <span>{{ personalInfo.driving_license }}</span>\r\n          </div>\r\n          <div class=\"info-item\" v-for=\"(link, i) in personalInfo.socialLinks\" :key=\"i\">\r\n            <span class=\"label\">{{ link.platform }}:</span>\r\n            <span :style=\"{ color: personalInfo.theme.linkColor }\">{{ link.url }}</span>\r\n          </div>\r\n        </div>\r\n\r\n\r\n        <section class=\"objective\" v-if=\"section.key === \'summary\' && personalInfo.summary\">\r\n          <h2>{{sectionTitles.summary}}</h2>\r\n          <p class=\"size12\">{{ personalInfo.summary }}</p>\r\n        </section>\r\n\r\n        <section class=\"section activities\" v-if=\"section.key === \'additionalSections\' && personalInfo.additionalSections.length && personalInfo.additionalSections[0].field\">\r\n          <div class=\"activities-item objective\" v-for=\"(add, index) in personalInfo.additionalSections\" :key=\"index\">\r\n            <h2>{{ add.field }}</h2>\r\n            <p class=\"period\">{{ add.start_date }} - {{ add.end_date }}</p>\r\n            <p>{{ add.description }}</p>\r\n          </div>\r\n        </section>\r\n\r\n\r\n      </template>\r\n    </template>\r\n  </div>\r\n\r\n  \r\n</main>', '.size12{\r\nfont-size: 12px;\r\n}\r\n\r\n\r\n.resume {\r\n    display: flex;\r\n    background: white;\r\n    box-shadow: 0 0 20px rgba(0, 0, 0, 0.1);\r\n    border-radius: 8px;\r\n    overflow: hidden;\r\n\r\n     font-family: \"Segoe UI\", Tahoma, Geneva, Verdana, sans-serif;\r\n    background-color: #f5f5f5;\r\n    color: #333;\r\n    line-height: 1.6;\r\n}\r\n\r\n.left-column {\r\n    flex: 2;\r\n    padding: 2rem;\r\n    background: white;\r\n}\r\n\r\n.right-column {\r\n    flex: 1;\r\n    padding: 2rem;\r\n    background: #2a9d8f;\r\n    color: white;\r\n}\r\n\r\n.section {\r\n    margin-bottom: 2rem;\r\n}\r\n\r\n.section-title {\r\n    color: #2a9d8f;\r\n    font-size: 1.2rem;\r\n    font-weight: 600;\r\n    margin-bottom: 1rem;\r\n    padding-bottom: 0.5rem;\r\n    border-bottom: 2px solid #2a9d8f;\r\n}\r\n\r\n.profile {\r\n    text-align: center;\r\n    margin-bottom: 2rem;\r\n}\r\n\r\n.profile-image {\r\n    width: 150px;\r\n    height: 150px;\r\n    margin: 0 auto 1rem;\r\n    border-radius: 50%;\r\n    overflow: hidden;\r\n    border: 3px solid white;\r\n}\r\n\r\n.profile-image img {\r\n    width: 100%;\r\n    height: 100%;\r\n    object-fit: cover;\r\n}\r\n\r\n.profile h1 {\r\n    font-size: 1.8rem;\r\n    margin-bottom: 0.5rem;\r\ncolor: #FFF;\r\n}\r\n\r\n.profile .title {\r\n    font-size: 1.1rem;\r\n    opacity: 0.9;\r\n}\r\n\r\n.contact-info {\r\n    margin-bottom: 2rem;\r\n}\r\n\r\n.info-item {\r\n    margin-bottom: 0.5rem;\r\n    display: flex\r\n\r\n}\r\n\r\n.info-item .label {\r\n    font-weight: 600;\r\n    margin-right: 0.5rem;\r\n}\r\n\r\n.objective,\r\n.interests {\r\n    margin-bottom: 2rem;\r\n}\r\n\r\n.objective h2,\r\n.interests h2 {\r\n    color: white;\r\n    font-size: 1.2rem;\r\n    margin-bottom: 1rem;\r\n    padding-bottom: 0.5rem;\r\n    border-bottom: 2px solid white;\r\n}\r\n\r\n.interests ul {\r\n    list-style: none;\r\n}\r\n\r\n.interests li {\r\n    margin-bottom: 0.5rem;\r\n}\r\n\r\n.education-item,\r\n.work-item,\r\n.activities-item {\r\n    margin-bottom: 1.5rem;\r\n}\r\n\r\n\r\n\r\nh3 {\r\n    color: #264653;\r\n    margin-bottom: 0.5rem;\r\n}\r\n\r\n.period {\r\n    color: #666;\r\n    font-size: 0.9rem;\r\n    margin-bottom: 0.5rem;\r\n}\r\n\r\n.position {\r\n    color: #2a9d8f;\r\n    font-weight: 500;\r\n    margin-bottom: 0.5rem;\r\n}\r\n\r\nul {\r\n    list-style-position: inside;\r\n    margin-left: 1rem;\r\n}\r\n\r\nli {\r\n    margin-bottom: 0.5rem;\r\n}\r\n\r\n.skill-item {\r\n    margin-bottom: 1rem;\r\n}\r\n\r\n.skill-name {\r\n    margin-bottom: 0.3rem;\r\n}\r\n\r\n.skill-bar {\r\n    height: 8px;\r\n    background: #e9ecef;\r\n    border-radius: 4px;\r\n    overflow: hidden;\r\n}\r\n\r\n.skill-level {\r\n    height: 100%;\r\n    background: #2a9d8f;\r\n    border-radius: 4px;\r\n}\r\n\r\n.reference-item p {\r\n    margin-bottom: 0.3rem;\r\n}\r\n\r\n@media (max-width: 768px) {\r\n    .resume {\r\n        flex-direction: column;\r\n    }\r\n\r\n    .right-column {\r\n        order: -1;\r\n    }\r\n\r\n    .profile-image {\r\n        width: 120px;\r\n        height: 120px;\r\n    }\r\n}', '[\r\n  { \"key\": \"personalInfo\", \"column\": \"right\" },\r\n  { \"key\": \"summary\", \"column\": \"right\" },\r\n  { \"key\": \"education\", \"column\": \"left\" },\r\n  { \"key\": \"employmentHistory\", \"column\": \"left\" },\r\n  { \"key\": \"skillsList\", \"column\": \"left\" },\r\n  { \"key\": \"languagesList\", \"column\": \"left\" },\r\n  { \"key\": \"socialLinks\", \"column\": \"right\" },\r\n{ \"key\": \"color\", \"column\": \"right\" },\r\n  { \"key\": \"additionalSections\", \"column\": \"right\" }\r\n]', 0, 'active', 1, '2025-04-09 05:13:01', '2025-05-19 07:05:39', NULL),
(14, '46', '[{\"value\":\"ssd\"},{\"value\":\"sdsdgsd\"},{\"value\":\"sdsgsdg\"}]', '[{\"value\":\"sdgsd\"},{\"value\":\"sdsdsdg\"}]', 'uploads/resume/67f61e41cc76b.png', '<div data-v-8d211864=\"\" class=\"tab-content pt-0\" id=\"myTabContent\">\n    <div data-v-8d211864=\"\" class=\"tab-pane fade show active\" id=\"AllTemplates\" role=\"tabpanel\" aria-labelledby=\"AllTemplates-tab\">\n        <div data-v-8d211864=\"\" class=\"row mt-0\">\n            <div data-v-8d211864=\"\" class=\"col-md-12 mt-0 mb-10\">\n                <div data-v-8d211864=\"\" class=\"rela-block page\">\n                    <div data-v-8d211864=\"\" class=\"rela-block top-bar\">\n                        <div data-v-8d211864=\"\" class=\"caps name\">\n                            <div data-v-8d211864=\"\" class=\"abs-center\"> {{ personalInfo.name }} </div>\n                        </div>\n                    </div>\n                    <div data-v-8d211864=\"\" class=\"side-bar\">\n                        <div data-v-8d211864=\"\" class=\"mugshot\">\n                            <div data-v-8d211864=\"\" class=\"logo\"><img data-v-8d211864=\"\" src=\"/assets/media/khaled.jpg\" class=\"avatar\" alt=\"avatar\"></div>\n                        </div>\n                        <p data-v-8d211864=\"\">{{ personalInfo.address }}</p>\n                        <p data-v-8d211864=\"\">{{ personalInfo.city }}, {{ personalInfo.country }} {{ personalInfo.postal_code }}</p>\n                        <p data-v-8d211864=\"\">{{ personalInfo.mobile }}</p>\n                        <p data-v-8d211864=\"\"> {{ personalInfo.email }} </p>\n                        <br data-v-8d211864=\"\">\n                        <p data-v-8d211864=\"\" class=\"rela-block social\" v-for=\"social in personalInfo.websitesAndSocialLinks\" :key=\"social.id\"> {{ social.label }} </p>\n                        <p data-v-8d211864=\"\" class=\"rela-block caps side-header\"> Expertise </p>\n                        <p data-v-8d211864=\"\" class=\"rela-block list-thing\" v-for=\"skill in personalInfo.skills\" :key=\"skill.id\"> {{ skill.skill }} </p>\n                        <p data-v-8d211864=\"\" class=\"rela-block caps side-header\"> Education </p>\n                        <p data-v-8d211864=\"\" class=\"rela-block list-thing\" v-for=\"educationItem in personalInfo.education\" :key=\"educationItem.id\"> {{ educationItem.degree }} </p>\n                        <p data-v-8d211864=\"\" class=\"rela-block list-thing\" v-for=\"educationItem in personalInfo.education\" :key=\"educationItem.id\"> {{ educationItem.school }} </p>\n                        </div>\n                    <div data-v-8d211864=\"\" class=\"rela-block content-container\">\n                        <h2 data-v-8d211864=\"\" class=\"rela-block caps title\"> {{ personalInfo.job_title }} </h2>\n                        <div data-v-8d211864=\"\" class=\"rela-block separator\"></div>\n                        <div data-v-8d211864=\"\" class=\"rela-block caps greyed\"> Profile </div>\n                        <p data-v-8d211864=\"\" class=\"long-margin\"> {{ personalInfo.summary }} </p>\n                        <div data-v-8d211864=\"\" class=\"section-wrapper clearfix\">\n                            <p data-v-8d211864=\"\" class=\"rela-block caps side-header\"> Skills </p>\n                            <ul data-v-8d211864=\"\">\n                                <li data-v-8d211864=\"\" class=\"skill-percentage\" v-for=\"skill in personalInfo.skills\" :key=\"skill.id\"> {{ skill.skill }} <span v-if=\"skill.level\">/ {{ skill.level }}</span> </li>\n                            </ul>\n                        </div>\n                        <p data-v-8d211864=\"\" class=\"rela-block caps side-header\"> Experience </p>\n                        <template v-for=\"(job, index) in personalInfo.employmentHistory\" :key=\"index\">\n                            <h3 data-v-8d211864=\"\">{{ job.job_title }}</h3>\n                            <p data-v-8d211864=\"\" class=\"light\">{{ job.employer }}</p>\n                            <p data-v-8d211864=\"\" class=\"justified\">{{ job.descriptions }}</p>\n                        </template>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n    </div>', 'شسب', NULL, 0, 'active', 1, '2025-04-09 05:14:09', '2025-04-15 15:05:54', NULL);
INSERT INTO `template_resumes` (`id`, `category_id`, `tags_en`, `tags_ar`, `logo`, `content_html`, `content_css`, `selectedSections`, `is_premium`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(15, '46', '[{\"value\":\"ssd\"},{\"value\":\"sdsdgsd\"},{\"value\":\"sdsgsdg\"}]', '[{\"value\":\"sdgsd\"},{\"value\":\"sdsdsdg\"}]', 'uploads/resume/682647a1a28dd.jfif', '<div class=\"resume\">\r\n  <div class=\"resume-header\">\r\n    <div class=\"header-left\">\r\n      <h4>{{ personalInfo.first_name }}<br />{{ personalInfo.last_name }}</h4>\r\n    </div>\r\n\r\n    <div class=\"header-right\">\r\n      <h2>{{ personalInfo.job_title }}</h2>\r\n\r\n      <div class=\"contact-info\">\r\n        <div class=\"contact-item\" v-if=\"personalInfo.mobile\">\r\n          <i class=\"ki-duotone ki-phone\"></i>\r\n          <span>{{ personalInfo.mobile }}</span>\r\n        </div>\r\n        <div class=\"contact-item\" v-if=\"personalInfo.email\">\r\n          <i class=\"ki-duotone ki-mail\"></i>\r\n          <span>{{ personalInfo.email }}</span>\r\n        </div>\r\n        <div class=\"contact-item\" v-if=\"personalInfo.city || personalInfo.country\">\r\n          <i class=\"ki-duotone ki-map-pin\"></i>\r\n          <span>{{ personalInfo.city }}, {{ personalInfo.country }}</span>\r\n        </div>\r\n        <div class=\"contact-item\" v-if=\"personalInfo.nationality\">\r\n          <i class=\"ki-duotone ki-globe\"></i>\r\n          <span>{{ personalInfo.nationality }}</span>\r\n        </div>\r\n        <div class=\"contact-item\" v-if=\"personalInfo.place_of_birth\">\r\n          <i class=\"ki-duotone ki-user\"></i>\r\n          <span>{{ personalInfo.place_of_birth }}</span>\r\n        </div>\r\n        <div class=\"contact-item\" v-if=\"personalInfo.date_of_birth\">\r\n          <i class=\"ki-duotone ki-calendar\"></i>\r\n          <span>{{ personalInfo.date_of_birth }}</span>\r\n        </div>\r\n        <div class=\"contact-item\" v-if=\"personalInfo.driving_license\">\r\n          <i class=\"ki-duotone ki-car\"></i>\r\n          <span>License: {{ personalInfo.driving_license }}</span>\r\n        </div>\r\n        <div class=\"contact-item\" v-if=\"personalInfo.postal_code\">\r\n          <i class=\"ki-duotone ki-hash\"></i>\r\n          <span>{{ personalInfo.postal_code }}</span>\r\n        </div>\r\n        <div class=\"contact-item col-md-12\" v-if=\"personalInfo.socialLinks.length\">\r\n          <i class=\"ki-duotone ki-link\"></i>\r\n          <span class=\"col-md-3\" v-for=\"(link, i) in personalInfo.socialLinks\" :key=\"i\">\r\n            {{ link.platform }}: {{ link.url }}<br />\r\n          </span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"resume-body\">\r\n    <div class=\"resume-left\">\r\n      <section class=\"summary\" v-if=\"personalInfo.summary\">\r\n        <h3>SUMMARY</h3>\r\n        <p>{{ personalInfo.summary }}</p>\r\n      </section>\r\n\r\n      <section class=\"skills\" v-if=\"personalInfo.skillsList.length\">\r\n        <h3>SKILLS</h3>\r\n        <div v-for=\"(skill, i) in personalInfo.skillsList\" :key=\"i\">\r\n          <strong>{{ skill.name }}</strong> - <small>{{ skill.level }}</small>\r\n        </div>\r\n      </section>\r\n\r\n      <section class=\"languages\" v-if=\"personalInfo.languagesList.length\">\r\n        <h3>LANGUAGES</h3>\r\n        <div v-for=\"(lang, i) in personalInfo.languagesList\" :key=\"i\">\r\n          <strong>{{ lang.name }}</strong> - <small>{{ lang.level }}</small>\r\n        </div>\r\n      </section>\r\n\r\n      <section class=\"additional\" v-if=\"personalInfo.additionalSections.length\">\r\n        \r\n        <div v-for=\"(sec, i) in personalInfo.additionalSections\" :key=\"i\">\r\n          <h3>{{ sec.field }}</h3>\r\n          <small v-if=\"sec.end_date\">{{ sec.start_date }} / {{ sec.end_date }}</small>\r\n<small v-else>{{ sec.start_date }} </small>\r\n          <p>{{ sec.description }}</p>\r\n        </div>\r\n      </section>\r\n    </div>\r\n\r\n    <div class=\"resume-right\">\r\n      <section class=\"experience\" v-if=\"personalInfo.employmentHistory.length\">\r\n        <h3>EXPERIENCE</h3>\r\n        <div v-for=\"(job, i) in personalInfo.employmentHistory\" :key=\"i\">\r\n          <h4>{{ job.job_title }}</h4>\r\n          <div>{{ job.company_name }}</div>\r\n          <div>{{ job.duration }}</div>\r\n          <p>{{ job.job_description }}</p>\r\n        </div>\r\n      </section>\r\n\r\n      <section class=\"education\" v-if=\"personalInfo.education.length\">\r\n        <h3>EDUCATION</h3>\r\n        <div v-for=\"(edu, i) in personalInfo.education\" :key=\"i\">\r\n          <h4>{{ edu.degree }}</h4>\r\n          <div>{{ edu.school }} - {{ edu.field }}</div>\r\n          <div>{{ edu.start_date }} - {{ edu.end_date }}</div>\r\n          <p>{{ edu.descriptions }}</p>\r\n        </div>\r\n      </section>\r\n    </div>\r\n  </div>\r\n</div>', '.resume {\r\n    background: white;\r\n    max-width: 1400px;\r\n    margin: 0 auto;\r\n    box-shadow: 0 0 40px rgba(0, 0, 0, 0.1);\r\n    border-radius: 0.5rem;\r\n    overflow: hidden;\r\n\r\n    font-family: system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\",\r\n        Roboto, Oxygen, Ubuntu, Cantarell, \"Open Sans\", \"Helvetica Neue\",\r\n        sans-serif;\r\n    background-color: #f3f6f9;\r\n    color: #464e5f;\r\n    line-height: 1.6;\r\n}\r\n\r\n/* Header Styles */\r\n.resume-header {\r\n    display: flex;\r\n    flex-direction: column;\r\n}\r\n\r\n.header-left {\r\n    background-color: #1e3a5f;\r\n    padding: 2rem;\r\n    color: white;\r\n}\r\n\r\n\r\n.header-left * {\r\n    color: white;\r\n}\r\n\r\n\r\n.resume-left * {\r\n    color: white;\r\n}\r\n\r\n.header-left h1 {\r\n    font-size: 2.5rem;\r\n    line-height: 1.2;\r\n    font-weight: 700;\r\n}\r\n\r\n.header-right {\r\n    padding: 1.5rem;\r\n}\r\n\r\n.header-right h2 {\r\n    color: #3699ff;\r\n    font-size: 1.5rem;\r\n    margin-bottom: 1rem;\r\n}\r\n\r\n.contact-info {\r\n    display: grid;\r\n    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\r\n    gap: 0.5rem;\r\n}\r\n\r\n.contact-item {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 0.5rem;\r\n    color: #464e5f;\r\n}\r\n\r\n.contact-item svg {\r\n    color: #3699ff;\r\n}\r\n\r\n/* Body Styles */\r\n.resume-body {\r\n    display: flex;\r\n    flex-direction: column;\r\n}\r\n\r\n.resume-left {\r\n    background-color: #1e3a5f;\r\n    color: white;\r\n    padding: 2rem;\r\n}\r\n\r\n.resume-right {\r\n    padding: 2rem;\r\n    background: white;\r\n}\r\n\r\n/* Section Styles */\r\nsection {\r\n    margin-bottom: 2rem;\r\n}\r\n\r\nh3 {\r\n    font-size: 1.25rem;\r\n    font-weight: 600;\r\n    padding-bottom: 0.5rem;\r\n    margin-bottom: 1rem;\r\n    border-bottom: 1px solid rgba(255, 255, 255, 0.1);\r\n}\r\n\r\n.resume-right h3 {\r\n    color: #464e5f;\r\n    border-bottom-color: #e4e6ef;\r\n}\r\n\r\n/* Achievement Items */\r\n.achievement-item {\r\n    display: flex;\r\n    gap: 1rem;\r\n    margin-bottom: 1.5rem;\r\n    transition: transform 0.3s ease;\r\n}\r\n\r\n.achievement-item:hover {\r\n    transform: translateX(0.25rem);\r\n}\r\n\r\n.achievement-item svg {\r\n    color: #3699ff;\r\n    flex-shrink: 0;\r\n    margin-top: 0.25rem;\r\n}\r\n\r\n.achievement-item h4 {\r\n    font-size: 1.125rem;\r\n    margin-bottom: 0.25rem;\r\n}\r\n\r\n.achievement-item p {\r\n    color: #b5b5c3;\r\n    font-size: 0.875rem;\r\n}\r\n\r\n/* Skills */\r\n.skills-list {\r\n    color: #b5b5c3;\r\n}\r\n\r\n/* Training Items */\r\n.training-item {\r\n    margin-bottom: 1.5rem;\r\n    transition: transform 0.3s ease;\r\n}\r\n\r\n.training-item:hover {\r\n    transform: translateX(0.25rem);\r\n}\r\n\r\n.training-item h4 {\r\n    font-size: 1.125rem;\r\n    margin-bottom: 0.25rem;\r\n    transition: color 0.3s ease;\r\n}\r\n\r\n.training-item:hover h4 {\r\n    color: #3699ff;\r\n}\r\n\r\n.training-item p {\r\n    color: #b5b5c3;\r\n    font-size: 0.875rem;\r\n}\r\n\r\n/* Experience Items */\r\n.experience-item {\r\n    margin-bottom: 2rem;\r\n}\r\n\r\n.experience-header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    margin-bottom: 0.5rem;\r\n}\r\n\r\n.experience-header h4 {\r\n    font-size: 1.25rem;\r\n    color: #464e5f;\r\n    transition: color 0.3s ease;\r\n}\r\n\r\n.experience-item:hover .experience-header h4 {\r\n    color: #3699ff;\r\n}\r\n\r\n.experience-subheader {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    margin-bottom: 1rem;\r\n}\r\n\r\n.company {\r\n    color: #3699ff;\r\n    font-weight: 500;\r\n}\r\n\r\n.location {\r\n    color: #b5b5c3;\r\n}\r\n\r\n.experience-item ul {\r\n    list-style: none;\r\n}\r\n\r\n.experience-item li {\r\n    display: flex;\r\n    gap: 0.5rem;\r\n    margin-bottom: 0.5rem;\r\n}\r\n\r\n.experience-item li::before {\r\n    content: \"•\";\r\n    color: #3699ff;\r\n    font-weight: bold;\r\n}\r\n\r\n/* Education Items */\r\n.education-item {\r\n    margin-bottom: 1.5rem;\r\n}\r\n\r\n.education-header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    margin-bottom: 0.5rem;\r\n}\r\n\r\n.education-header h4 {\r\n    font-size: 1.25rem;\r\n    color: #464e5f;\r\n    transition: color 0.3s ease;\r\n}\r\n\r\n.education-item:hover .education-header h4 {\r\n    color: #3699ff;\r\n}\r\n\r\n.education-subheader {\r\n    display: flex;\r\n    justify-content: space-between;\r\n}\r\n\r\n.school {\r\n    color: #3699ff;\r\n    font-weight: 500;\r\n}\r\n\r\n/* Footer */\r\n.powered-by {\r\n    margin-top: 2rem;\r\n    padding-top: 1rem;\r\n    border-top: 1px solid rgba(255, 255, 255, 0.1);\r\n    font-size: 0.875rem;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 0.5rem;\r\n}\r\n\r\n.enhancv {\r\n    font-weight: 600;\r\n}\r\n\r\n.website {\r\n    text-align: right;\r\n    color: #b5b5c3;\r\n    font-size: 0.875rem;\r\n    margin-top: 1.5rem;\r\n}\r\n\r\n/* Responsive Design */\r\n@media (min-width: 768px) {\r\n    .resume-header {\r\n        flex-direction: row;\r\n    }\r\n\r\n    .header-left {\r\n        width: 25%;\r\n    }\r\n\r\n    .header-right {\r\n        width: 75%;\r\n    }\r\n\r\n    .resume-body {\r\n        flex-direction: row;\r\n    }\r\n\r\n    .resume-left {\r\n        width: 25%;\r\n    }\r\n\r\n    .resume-right {\r\n        width: 75%;\r\n    }\r\n}', NULL, 0, 'active', 1, '2025-04-09 05:14:49', '2025-05-15 18:42:31', NULL),
(16, '42', '[{\"value\":\"aaaa\"},{\"value\":\"aaa\"},{\"value\":\"aa\"}]', '[{\"value\":\"طط\"},{\"value\":\"ططط\"},{\"value\":\"طططط\"}]', 'uploads/resume/681b6dcbd5c07.jpg', '<main class=\"resume\">\r\n  <template v-for=\"section in selectedSections\" :key=\"section\">\r\n    <!-- EDUCATION -->\r\n    <div v-if=\"section === \'education\'\" class=\"left-column\" :style=\"{ fontFamily: personalInfo.theme.fontFamily }\">\r\n      <section class=\"section education\" v-if=\"personalInfo.education.length\">\r\n        <h2 class=\"section-title\" :style=\"{ color: personalInfo.theme.titleColor, borderBottom: \'2px solid \' + personalInfo.theme.titleColor }\">EDUCATION</h2>\r\n        <div class=\"education-item\" v-for=\"(edu, index) in personalInfo.education\" :key=\"index\">\r\n          <h3>{{ edu.school }}</h3>\r\n          <p class=\"period\">{{ edu.start_date }} - {{ edu.end_date }}</p>\r\n          <p>Major: {{ edu.field }}</p>\r\n          <p>{{ edu.degree }}</p>\r\n          <p>{{ edu.descriptions}}</p>\r\n        </div>\r\n      </section>\r\n    </div>\r\n\r\n    <!-- WORK EXPERIENCE -->\r\n    <div v-if=\"section === \'employmentHistory\'\" class=\"left-column\" :style=\"{ fontFamily: personalInfo.theme.fontFamily }\">\r\n      <section class=\"section work\" v-if=\"personalInfo.employmentHistory.length\">\r\n        <h2 class=\"section-title\" :style=\"{ color: personalInfo.theme.titleColor, borderBottom: \'2px solid \' + personalInfo.theme.titleColor }\">WORK EXPERIENCE</h2>\r\n        <div class=\"work-item\" v-for=\"(job, index) in personalInfo.employmentHistory\" :key=\"index\">\r\n          <h3>{{ job.company_name }}</h3>\r\n          <p class=\"period\">{{ job.duration }}</p>\r\n          <p class=\"position\" :style=\"{ color: personalInfo.theme.titleColor }\">{{ job.job_title }}</p>\r\n          <ul>\r\n            <li>{{ job.job_description }}</li>\r\n          </ul>\r\n        </div>\r\n      </section>\r\n    </div>\r\n\r\n    <!-- SKILLS -->\r\n    <div v-if=\"section === \'skillsList\'\" class=\"left-column\" :style=\"{ fontFamily: personalInfo.theme.fontFamily }\">\r\n      <section class=\"section skills\" v-if=\"personalInfo.skillsList.length\">\r\n        <h2 class=\"section-title\" :style=\"{ color: personalInfo.theme.titleColor, borderBottom: \'2px solid \' + personalInfo.theme.titleColor }\">SKILLS</h2>\r\n        <div class=\"skill-item\" v-for=\"(skill, index) in personalInfo.skillsList\" :key=\"index\">\r\n          <div class=\"skill-name\">{{ skill.name }}</div>\r\n          <div class=\"skill-bar\">\r\n            <div class=\"skill-level\" :style=\"{ width: skill.percentage, background: personalInfo.theme.barColor }\"></div>\r\n          </div>\r\n        </div>\r\n      </section>\r\n    </div>\r\n\r\n    <!-- LANGUAGES -->\r\n    <div v-if=\"section === \'languagesList\'\" class=\"left-column\" :style=\"{ fontFamily: personalInfo.theme.fontFamily }\">\r\n      <section class=\"section skills\" v-if=\"personalInfo.languagesList.length\">\r\n        <h2 class=\"section-title\" :style=\"{ color: personalInfo.theme.titleColor, borderBottom: \'2px solid \' + personalInfo.theme.titleColor }\">Languages</h2>\r\n        <div class=\"skill-item\" v-for=\"(lang, index) in personalInfo.languagesList\" :key=\"index\">\r\n          <div class=\"skill-name\">{{ lang.name }}</div>\r\n          <div class=\"skill-bar\">\r\n            <div class=\"skill-level\" :style=\"{ width: lang.percentage, background: personalInfo.theme.barColor }\"></div>\r\n          </div>\r\n        </div>\r\n      </section>\r\n    </div>\r\n\r\n    <!-- ADDITIONAL SECTIONS -->\r\n    <div v-if=\"section === \'additionalSections\'\" class=\"right-column\" :style=\"{ background: personalInfo.theme.sidebarBgColor, fontFamily: personalInfo.theme.fontFamily }\">\r\n      <section class=\"section activities\" v-if=\"personalInfo.additionalSections.length\">\r\n        <div class=\"activities-item objective\" v-for=\"(add, index) in personalInfo.additionalSections\" :key=\"index\" v-if=\"add.field\">\r\n          <h2>{{ add.field }}</h2>\r\n          <p class=\"period\">{{ add.start_date }} - {{ add.end_date }}</p>\r\n          <p>{{ add.description }}</p>\r\n        </div>\r\n      </section>\r\n    </div>\r\n\r\n    <!-- SUMMARY / BIO -->\r\n    <div v-if=\"section === \'summary\'\" class=\"right-column\" :style=\"{ background: personalInfo.theme.sidebarBgColor, fontFamily: personalInfo.theme.fontFamily }\">\r\n      <section class=\"objective\" v-if=\"personalInfo.summary\">\r\n        <h2>BIO</h2>\r\n        <p class=\"size12\">{{ personalInfo.summary }}</p>\r\n      </section>\r\n    </div>\r\n\r\n    <!-- PERSONAL INFO -->\r\n    <div v-if=\"section === \'personalInfo\'\" class=\"right-column\" :style=\"{ background: personalInfo.theme.sidebarBgColor, fontFamily: personalInfo.theme.fontFamily }\">\r\n      <div class=\"profile\">\r\n        <div class=\"profile-image\">\r\n          <img :src=\"personalInfo.logo\" alt=\"Profile photo\" />\r\n        </div>\r\n        <h1>{{ personalInfo.first_name }} {{ personalInfo.last_name }}</h1>\r\n        <p class=\"title\">{{ personalInfo.job_title }}</p>\r\n      </div>\r\n\r\n      <div class=\"contact-info\">\r\n        <div class=\"info-item\" v-if=\"personalInfo.place_of_birth\">\r\n          <span class=\"label\">Place of Birth:</span>\r\n          <span>{{ personalInfo.place_of_birth}}</span>\r\n        </div>\r\n        <div class=\"info-item\" v-if=\"personalInfo.date_of_birth\">\r\n          <span class=\"label\">Date of Birth:</span>\r\n          <span>{{ personalInfo.date_of_birth }}</span>\r\n        </div>\r\n        <div class=\"info-item\" v-if=\"personalInfo.email\">\r\n          <span class=\"label\">Mail:</span>\r\n          <span>{{ personalInfo.email }}</span>\r\n        </div>\r\n        <div class=\"info-item\" v-if=\"personalInfo.mobile\">\r\n          <span class=\"label\">Phone:</span>\r\n          <span>{{ personalInfo.mobile }}</span>\r\n        </div>\r\n        <div class=\"info-item\" v-if=\"personalInfo.address\">\r\n          <span class=\"label\">Address:</span>\r\n          <span>{{ personalInfo.address }} - {{ personalInfo.city }} - {{ personalInfo.country }}</span>\r\n        </div>\r\n        <div class=\"info-item\" v-if=\"personalInfo.nationality\">\r\n          <span class=\"label\">Nationality:</span>\r\n          <span>{{ personalInfo.nationality}}</span>\r\n        </div>\r\n        <div class=\"info-item\" v-if=\"personalInfo.postal_code\">\r\n          <span class=\"label\">Postal Code:</span>\r\n          <span>{{ personalInfo.postal_code}}</span>\r\n        </div>\r\n        <div class=\"info-item\" v-if=\"personalInfo.driving_license\">\r\n          <span class=\"label\">Driving License:</span>\r\n          <span>{{ personalInfo.driving_license}}</span>\r\n        </div>\r\n        <div class=\"info-item\" v-for=\"(link, i) in personalInfo.socialLinks\" :key=\"i\">\r\n          <span class=\"label\">{{ link.platform }}:</span>\r\n          <span :style=\"{ color: personalInfo.theme.linkColor }\">{{ link.url }}</span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </template>\r\n</main>', 'null', NULL, 0, 'active', 1, '2025-04-14 17:29:01', '2025-05-16 16:43:13', NULL),
(7, '42', '[{\"value\":\"acas\"},{\"value\":\"asvasv\"},{\"value\":\"asas\"},{\"value\":\"afafg\"}]', '[{\"value\":\"adccas\"},{\"value\":\"avasv\"},{\"value\":\"avas\"},{\"value\":\"dvsdv\"}]', 'uploads/resume/67f61bc9568c6.png', '<div class=\"resume\">\r\n  <!-- قسم المعلومات الشخصية -->\r\n  <div class=\"personal-info\">\r\n\r\n    <h3>{{ sectionTitles.personalInfo }}</h3>\r\n\r\n\r\n    <img :src=\"personalInfo.logo || \'https://via.placeholder.com/150\'\" alt=\"Profile Photo\">\r\n    <h1>{{ personalInfo.first_name }} {{ personalInfo.last_name }}</h1>\r\n    <h2>{{ personalInfo.job_title }}</h2>\r\n    <p><strong>Email:</strong> {{ personalInfo.email }}</p>\r\n    <p><strong>Phone:</strong> {{ personalInfo.mobile }}</p>\r\n    <p>\r\n      <strong>Address:</strong> {{ personalInfo.address }}, \r\n      {{ personalInfo.city }}, \r\n      {{ personalInfo.country }}\r\n    </p>\r\n    <p><strong>Postal Code:</strong> {{ personalInfo.postal_code }}</p>\r\n    <p><strong>Driving License:</strong> {{ personalInfo.driving_license }}</p>\r\n    <p><strong>Nationality:</strong> {{ personalInfo.nationality }}</p>\r\n    <p><strong>Place of Birth:</strong> {{ personalInfo.place_of_birth }}</p>\r\n    <p><strong>Date of Birth:</strong> {{ personalInfo.date_of_birth }}</p>\r\n  </div>\r\n\r\n  <!-- قسم الملخص -->\r\n  <div class=\"summary\">\r\n\r\n    <h3>{{ sectionTitles.summary }}</h3>\r\n    <p>{{ personalInfo.summary }}</p>\r\n  </div>\r\n\r\n  <!-- قسم الخبرات العملية -->\r\n  <div class=\"employment-history\">\r\n    <h3>{{ sectionTitles.employmentHistory }}</h3>\r\n    <div v-for=\"job in personalInfo.employmentHistory\" :key=\"index\">\r\n      <p>{{ job.job_title }}- {{ job.employer }}</p>\r\n      <p>Dates: {{ job.start_date }} - {{ job.end_date }}</p>\r\n      <p>City: {{ job.city }}</p>\r\n      <p>{{ job.descriptions }}</p>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- قسم التعليم -->\r\n  <div class=\"education\">\r\n    <h3>{{ sectionTitles.education }}</h3>\r\n    <div v-for=\"edu in personalInfo.education\" :key=\"index\">\r\n      <p>{{ edu.degree }} - {{ edu.school }}</p>\r\n      <p>Dates: {{ edu.start_date }} - {{ edu.end_date }}</p>\r\n      <p>City: {{ edu.city }}</p>\r\n      <p>{{ edu.descriptions }}</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"websites-social-links\">\r\n    <h3>{{ sectionTitles.websitesAndSocialLinks }}</h3>\r\n    <div v-for=\"social in personalInfo.websitesAndSocialLinks\" :key=\"index\">\r\n      <p>{{ social.label }}: <a :href=\"social.link\" target=\"_blank\">{{ social.link }}</a></p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"skills\">\r\n    <h3>{{ sectionTitles.skills }}</h3>\r\n    <div v-for=\"skill in personalInfo.skills\" :key=\"index\">\r\n      <p>{{ skill.skill }}: {{ skill.level }}</p>\r\n    </div>\r\n  </div>\r\n\r\n\r\n</div>', 'asvas', NULL, 0, 'active', 1, '2025-01-24 17:16:51', '2025-04-09 05:03:37', NULL);
